    var t = e.t.toLowerCase(), pts = 0;
    for (var i = 0; i < terms.length; i++) {
      var w = terms[i];
      if (!w) continue;
      if (hay.indexOf(w) === -1) return 0;      /* every word must match somewhere */
      pts += t.indexOf(w) !== -1 ? 3 : (e.k.toLowerCase().indexOf(w) !== -1 ? 2 : 1);
    }
    return pts;
  }
