    rows = []; sel = -1;
    if (!list.length) {
      box.innerHTML = '<div class="hs-none">Can&rsquo;t find it? Call <a href="tel:0249334667">02 4933 4667</a> or <a href="/contact#enquiry">send us a message</a> - we&rsquo;ll point you the right way.</div>';
      return;
    }
    list.forEach(function (e) {
      var a = document.createElement('a');
      a.className = 'hs-row'; a.href = e.u; a.setAttribute('role', 'option');
      a.innerHTML = (e.i ? '<span class="vm-thumb"><img src="' + e.i + '" alt="" loading="lazy"></span>' : '') +
        '<span class="vm-txt"><b>' + e.t + '</b><span>' + e.d + '</span></span>';
      box.appendChild(a); rows.push(a);
    });
  }
  function open(show) {
    box.hidden = !show;
    input.setAttribute('aria-expanded', show ? 'true' : 'false');
  }
  function update() {
    var q = input.value.trim().toLowerCase();
    if (q.length < 2) { open(false); return; }
    var terms = q.split(/\s+/).slice(0, 6);
    var hits = IX.map(function (e) { return [score(e, terms), e]; })
      .filter(function (x) { return x[0] > 0; })
      .sort(function (a, b) { return b[0] - a[0]; })
      .slice(0, 6).map(function (x) { return x[1]; });
    render(hits); open(true);
  }
  function mark() { rows.forEach(function (r, i) { r.classList.toggle('on', i === sel); }); }
  input.addEventListener('input', update);
  input.addEventListener('focus', function () { if (input.value.trim().length >= 2) update(); });
  input.addEventListener('keydown', function (e) {
    if (e.key === 'ArrowDown') { e.preventDefault(); if (rows.length) { sel = (sel + 1) % rows.length; mark(); } }
    else if (e.key === 'ArrowUp') { e.preventDefault(); if (rows.length) { sel = (sel - 1 + rows.length) % rows.length; mark(); } }
    else if (e.key === 'Enter') {
      e.preventDefault();
      var target = rows[sel >= 0 ? sel : 0];
      if (target) location.href = target.href;
    } else if (e.key === 'Escape') { open(false); input.blur(); }
  });
  document.addEventListener('click', function (e) {
    if (!document.getElementById('heroSearch').contains(e.target)) open(false);
  });
})();
